import { Fragment, StrictMode, useEffect, useState, type FormEvent, type ReactNode } from 'react'
import { createRoot } from 'react-dom/client'
import './styles.css'
import './admin-overrides.css'

type Page = 'home' | 'wallet' | 'orders' | 'international' | 'local' | 'profile' | 'request' | 'login' | 'favorites' | 'notifications' | 'drafts' | 'settings'

const API_BASE = import.meta.env.VITE_API_BASE_URL || 'http://localhost:3000/api'
async function apiRequest(path: string, options: RequestInit = {}) {
  const headers = new Headers(options.headers)
  headers.set('Content-Type', 'application/json')
  const response = await fetch(`${API_BASE}${path}`, { ...options, headers, credentials: 'include' })
  const payload = await response.json().catch(() => null)
  if (!response.ok) throw new Error(payload?.message || 'تعذر الاتصال بالخادم')
  return payload
}

